// Local demo configuration is generated by demo-start.ps1, never committed.
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const { Client } = require('pg');
const root = path.resolve(__dirname, '..');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

async function connectDemo() {
  const config = JSON.parse(
    fs
      .readFileSync(path.join(root, '.tmp/demo-config.json'), 'utf8')
      .replace(/^\uFEFF/, ''),
  );
  assert.equal(config.host, '127.0.0.1');
  assert.equal(config.port, 55439);
  assert.equal(config.user, 'foodbridge_demo');
  assert.equal(config.database, 'foodbridge_swagger_demo');
  const db = new Client({ ...config, connectionTimeoutMillis: 3000 });
  await db.connect();
  try {
    const {
      rows: [server],
    } = await db.query(
      "SELECT current_database() AS db, current_user AS usr, current_setting('data_directory') AS directory, current_setting('port') AS port",
    );
    assert.equal(server.db, config.database);
    assert.equal(server.usr, config.user);
    assert.equal(server.port, String(config.port));
    assert.equal(
      path.resolve(server.directory).toLowerCase(),
      path.join(root, '.tmp/pg-swagger-demo').toLowerCase(),
    );
    const { rows } = await db.query(
      "SELECT table_name FROM information_schema.tables WHERE table_schema='public'",
    );
    for (const table of [
      'users',
      'categories',
      'establishments',
      'food_publications',
      'requests',
      'pickups',
      'notifications',
    ]) {
      assert(
        rows.some((row) => row.table_name === table),
        `Missing schema: ${table}. Start NestJS first.`,
      );
    }
    return db;
  } catch (error) {
    await db.end();
    throw error;
  }
}

async function seedNotification(db, userId) {
  assert(uuid.test(userId), 'USER_ID must be a UUID');
  const { rows } = await db.query('SELECT id FROM users WHERE id=$1', [userId]);
  assert.equal(
    rows.length,
    1,
    'USER_ID does not exist in the isolated demo database',
  );
  const {
    rows: [notification],
  } = await db.query(
    'INSERT INTO notifications ("userId", title, message, "isRead") VALUES ($1, $2, $3, false) RETURNING id, "userId", "isRead"',
    [
      userId,
      'Demo FoodBridge',
      'Notificacion ficticia preparada fuera de camara',
    ],
  );
  assert.equal(notification.isRead, false);
  return notification;
}

module.exports = { connectDemo, seedNotification, uuid };
